<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900;display:flex;justify-content:space-between}header a{color:#ffd45c;text-decoration:none}main{max-width:1450px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}.add{display:flex;gap:10px}.add input{flex:1;font:inherit;border:2px solid #dbe5e8;border-radius:12px;padding:13px}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:10px 8px 0 0}.secondary{background:#fff}.participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.pill{background:#d8f4f4;border-radius:999px;padding:7px 12px;cursor:pointer}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:230px!important;height:230px!important;border:10px solid #fff}.fullscreen{position:fixed;inset:0;background:linear-gradient(#10283d,#174a62);color:#fff;z-index:50;overflow:auto;padding:clamp(18px,3vw,48px)}.race-top{display:flex;justify-content:space-between;align-items:center;gap:20px;max-width:1500px;margin:auto}.race-top h1{font-size:clamp(30px,5vw,70px);line-height:.9;margin:0;letter-spacing:-.06em}.timer{font-size:clamp(30px,5vw,70px);color:#ffd45c;font-weight:900}.circuit-wrap{max-width:1200px;margin:20px auto 0;position:relative}.circuit{position:relative;width:100%;aspect-ratio:2.1/1;border:clamp(22px,4vw,46px) solid #355c69;border-radius:50%;box-shadow:inset 0 0 0 5px #87d8dc,0 0 0 4px #ffd45c;background:repeating-linear-gradient(0deg,#4f897d 0 9px,#4a8378 9px 18px);overflow:hidden}.circuit:before{content:'🏁';position:absolute;right:2%;top:42%;font-size:clamp(25px,4vw,50px);z-index:4}.circuit:after{content:'PATO GRAND PRIX';position:absolute;inset:38% 30%;border:3px dashed rgba(255,255,255,.35);border-radius:50%;display:grid;place-items:center;color:rgba(255,255,255,.55);font-weight:900;font-size:clamp(12px,2vw,26px);letter-spacing:.1em}.duck{position:absolute;left:0;top:0;z-index:5;font-size:clamp(30px,4vw,55px);offset-path:ellipse(43% 38% at 50% 50%);offset-rotate:auto;animation:lap var(--time) linear var(--delay) forwards}.duck .name{display:block;margin-top:-3px;background:var(--color);color:#10283d;font-size:clamp(10px,1.2vw,16px);font-weight:900;padding:4px 9px;border-radius:999px;white-space:nowrap;transform:rotate(0deg)}@keyframes lap{0%{offset-distance:0%;transform:scale(1)}50%{transform:scale(1.06)}100%{offset-distance:100%;transform:scale(1)}}.result{max-width:620px;margin:24px auto;background:#fff;color:#10283d;border-radius:18px;padding:18px;text-align:center}.muted{color:#9fc4ce;font-size:14px}@media(max-width:760px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.add{flex-direction:column}.circuit{aspect-ratio:1.25/1}}
</style></head><body><header><span>PATO NA PISTA 🦆</span><a href="/">← Voltar para home</a></header><main id="app"><div class="hero"><div><small>SALA @{{ race.code }}</small><h1>Prepare os patos.</h1><p>@{{ race.names.length }} participantes · atualização a cada segundo.</p></div><div style="font-size:90px">🦆</div></div><section class="panel"><div class="grid"><div class="full"><label>Cadastre os participantes</label><div class="add"><input v-model="newName" @keyup.enter="addName" placeholder="Digite um nome"><button @click="addName">Cadastrar nome</button></div><div class="participants"><span v-for="name in race.names" class="pill" @click="removeName(name)">@{{ name }} ×</span></div></div><div><label>Duração: <input style="width:80px;padding:9px" type="number" v-model.number="duration" min="5" max="300"> segundos</label><br><button @click="startRace">Começar corrida</button><button class="secondary" @click="openQr">QR em tela cheia</button><button class="secondary" @click="exportCsv">Exportar CSV</button></div><div class="qr"><div id="qrcode"></div><span>Escaneie para entrar<br>@{{ joinUrl }}</span></div></div></section><div v-if="raceScreen" class="fullscreen"><div class="race-top"><div><small>🏁 CIRCUITO AO VIVO · SALA @{{ race.code }}</small><h1>@{{ finished?'🏆 Temos um campeão!':'Volta em andamento' }}</h1></div><div><div class="timer">@{{ finished?'FIM':Math.ceil(remaining)+'s' }}</div><button class="secondary" @click="raceScreen=false">Sair</button></div></div><div class="circuit-wrap"><div class="circuit"><span v-for="(name,i) in race.names" class="duck" :style="duckStyle(name,i)">🦆<span class="name">@{{ name }}</span></span></div></div><div v-if="finished" class="result"><h2>🏆 @{{ winner }}</h2><strong>Campeão da corrida!</strong><ol><li v-for="r in race.results">@{{ r.position }}º — @{{ r.name }}</li></ol><button @click="raceScreen=false">Voltar ao painel</button></div></div><div v-if="showQr" class="fullscreen" style="background:#fffaf0;color:#10283d;display:grid;place-items:center"><div class="qr"><div><small>ESCANEIE PARA PARTICIPAR</small><h1>Pato na Pista</h1></div><div id="qrcodeFull"></div><button @click="showQr=false">Fechar</button></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:@json($race??null),newName:'',joinUrl:'',raceScreen:false,finished:false,showQr:false,order:[],winner:'',duration:60,remaining:60,poll:null,timer:null}},mounted(){this.setup()},methods:{setup(){this.joinUrl=location.origin+'/join/'+this.race.code;setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:230,height:230}),50);this.poll=setInterval(async()=>{if(!this.raceScreen){const r=await fetch('/api/races/'+this.race.code);if(r.ok)this.race=await r.json()}},1000)},async addName(){const name=this.newName.trim();if(!name)return;const r=await fetch('/api/races/'+this.race.code+'/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,session:'organizer-'+crypto.randomUUID()})});if(r.ok){this.race=await r.json();this.newName=''}else alert((await r.json()).message||'Não foi possível cadastrar')},async removeName(name){this.race.names=this.race.names.filter(n=>n!==name);await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.race.names})})},duckStyle(name,i){const rank=this.order.indexOf(name)<0?i:this.order.indexOf(name);const colors=['#ff7a59','#ffd45c','#6ed6c0','#8eb8ff','#f49bd8','#c7a6ff'];return{'--color':colors[i%colors.length],'--time':Math.max(4,this.duration+rank*.7)+'s','--delay':Math.random()*.2+'s'}},openQr(){this.showQr=true;setTimeout(()=>new QRCode(document.getElementById('qrcodeFull'),{text:this.joinUrl,width:520,height:520}),50)},async startRace(){if(this.race.names.length<2){alert('Cadastre pelo menos 2 participantes.');return}this.raceScreen=true;this.finished=false;this.remaining=this.duration;const next=await(await fetch('/api/races/'+this.race.code+'/start',{method:'POST'})).json();if(next.message){alert(next.message);this.raceScreen=false;return}this.order=next.results.map(r=>r.name);this.winner=this.order[0];this.timer=setInterval(()=>{this.remaining--;if(this.remaining<=0)clearInterval(this.timer)},1000);setTimeout(()=>{this.race=next;this.finished=true;clearInterval(this.timer)},this.duration*1000)},exportCsv(){const a=document.createElement('a');a.href='data:text/csv,nome,posicao%0A'+(this.race.results||[]).map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
